<template>
  <section class="admin-hub">
    <header><div><p class="rd-eyebrow">RD STUDIO</p><h1>管理后台</h1></div><button class="rd-icon-button" :disabled="loading||busy" aria-label="刷新管理数据" title="刷新" @click="load"><RefreshCw :size="20" /></button></header>
    <p v-if="loading" role="status">正在加载…</p><p v-if="error" role="alert">{{error}} <a v-if="unauthorized" href="/login">登录</a></p>
    <template v-if="overview">
      <div class="admin-metrics"><div><strong>{{overview.pending}}</strong><span>待处理申请</span></div><div><strong>{{overview.users}}</strong><span>注册用户</span></div><div><strong>{{overview.published}}</strong><span>已发布文章</span></div></div>
      <div class="admin-layout">
        <main>
          <nav class="rd-segments admin-tabs" aria-label="管理视图"><button v-for="option in tabs" :key="option.id" :aria-pressed="tab===option.id" :disabled="busy" @click="changeTab(option.id)">{{option.label}}</button></nav>
          <template v-if="tab==='queue'">
            <form class="admin-filter" @submit.prevent="offset=0;loadRows()"><label>类型<select v-model="kind" @change="offset=0;loadRows()"><option value="">全部申请 · {{overview.pending}}</option><option v-for="item in overview.queues" :key="item.kind" :value="item.kind">{{item.label}} · {{item.count}}</option></select></label><label class="admin-search">搜索<input v-model="query" type="search" maxlength="100" placeholder="标题或提交人"></label><button class="rd-icon-button" title="搜索申请" aria-label="搜索申请"><Search :size="18" /></button></form>
            <p v-if="rowLoading" role="status">加载待办…</p><p v-else-if="!rows.length" class="admin-empty">没有待处理申请</p>
            <article v-for="item in rows" :key="item.kind+item.id" class="admin-queue-row"><div class="admin-row-title"><span class="admin-kind">{{label(item.kind)}}</span><a :href="item.href">{{item.title}}</a></div><p>{{item.preview||'暂无补充说明'}}</p><footer><a :href="'/user/profile?id='+encodeURIComponent(item.user_id)">{{item.username||'未记录'}}</a><time>{{date(item.created_at)}}</time><a class="admin-review-link" :href="item.href">处理申请<ArrowUpRight :size="16" /></a></footer></article>
          </template>
          <template v-if="tab==='activity'"><p v-if="rowLoading" role="status">加载操作记录…</p><p v-else-if="!rows.length" class="admin-empty">暂无操作记录</p><article v-for="row in rows" :key="row.id" class="admin-queue-row"><div class="admin-row-title"><strong>{{row.action}}</strong><span>{{row.actor_name}}</span></div><p>{{row.detail||label(row.kind)}}</p><small>{{date(row.created_at)}} · {{label(row.kind)}} <span v-if="row.entity_id">· {{row.entity_id}}</span></small></article></template>
          <form v-if="tab==='notice'" class="admin-notice-form" @submit.prevent="preview">
            <label>通知标题<input v-model="form.title" required maxlength="100" :disabled="busy"></label><label>通知内容<textarea v-model="form.body" required maxlength="3000" rows="7" :disabled="busy" /></label>
            <div class="admin-form-grid"><label>接收范围<select v-model="form.audience" aria-label="接收范围" :disabled="busy" @change="form.user_id=''" required><option value="all">全体用户</option><option value="formal">正式社员及以上</option><option value="user">指定用户</option></select></label><label>站内链接<input v-model="form.href" placeholder="/messages/" maxlength="500" :disabled="busy"></label></div>
            <template v-if="form.audience==='user'"><label>查找用户<input v-model="personQuery" maxlength="100" :disabled="busy" @input="findPeople"></label><label>接收用户<select v-model="form.user_id" aria-label="接收用户" required :disabled="busy"><option value="" disabled>请选择</option><option v-for="person in people" :key="person.id" :value="person.id">{{person.username}} · {{person.xp}} EXP</option></select></label></template>
            <button class="rd-button rd-button-primary" :disabled="busy"><Send :size="17" />预览通知</button>
          </form>
          <nav v-if="tab!=='notice'&&(offset||more)" class="rd-pagination"><button class="rd-button" :disabled="rowLoading||!offset" @click="offset-=30;loadRows()">上一页</button><span>{{offset/30+1}}</span><button class="rd-button" :disabled="rowLoading||!more" @click="offset+=30;loadRows()">下一页</button></nav><p v-if="message" role="status">{{message}}</p>
        </main>
      </div>
    </template>
    <dialog ref="dialog" class="admin-notice-dialog" @cancel="cancel"><header><h2>确认发送通知</h2><button class="rd-icon-button" title="关闭预览" aria-label="关闭预览" :disabled="busy" @click="dialog.close()"><X :size="18" /></button></header><template v-if="prepared"><p class="admin-kind">{{prepared.recipient_count}} 位接收用户</p><h3>{{prepared.title}}</h3><p class="admin-preview-body">{{prepared.body}}</p><p>{{prepared.href}}</p><p v-if="sendError" role="alert">{{sendError}}</p><button class="rd-button rd-button-primary" :disabled="busy" @click="send"><Send :size="17" />{{busy?'发送中…':'确认发送'}}</button></template></dialog>
  </section>
</template>
<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {ArrowUpRight,RefreshCw,Search,Send,X} from 'lucide-vue-next'
import {communityRequest} from '../lib/community-api.mjs'
const overview=ref(null),rows=ref([]),loading=ref(true),rowLoading=ref(false),busy=ref(false),error=ref(''),unauthorized=ref(false),message=ref(''),sendError=ref(''),tab=ref('queue'),kind=ref(''),query=ref(''),offset=ref(0),more=ref(false),dialog=ref(null),prepared=ref(null),people=ref([]),personQuery=ref('')
const form=ref({title:'',body:'',href:'/messages/',audience:'all',user_id:''})
const tabs=[{id:'queue',label:'待办审核'},{id:'notice',label:'发送通知'},{id:'activity',label:'操作记录'}]
let disposed=false,revision=0,rowRevision=0,personRevision=0,subscription
const date=value=>new Date(value).toLocaleString('zh-CN'),label=kind=>overview.value?.queues.find(q=>q.kind===kind)?.label||({articles:'文章',profiles:'用户',profile_changes:'资料申请',knowledge_branches:'知识库',knowledge_branch_requests:'分支申请',notice:'站内通知',levels:'经验等级',member:'社员'}[kind])||kind
async function load(){const run=++revision;loading.value=true;error.value='';try{const data=await communityRequest('/admin/overview');if(disposed||run!==revision)return;overview.value=data;unauthorized.value=false;await loadRows()}catch(e){if(run===revision&&!disposed){overview.value=null;rows.value=[];error.value=e.message;unauthorized.value=e.status===401}}finally{if(run===revision)loading.value=false}}
async function loadRows(){const run=++rowRevision;rows.value=[];more.value=false;if(tab.value==='notice'){rowLoading.value=false;return}rowLoading.value=true;error.value='';try{const path=tab.value==='queue'?'/admin/queue?'+new URLSearchParams({kind:kind.value,q:query.value,offset:offset.value}):'/admin/activity?offset='+offset.value;const result=await communityRequest(path);if(!disposed&&run===rowRevision){rows.value=result.items;more.value=result.has_more}}catch(e){if(run===rowRevision&&!disposed)error.value=e.message}finally{if(run===rowRevision)rowLoading.value=false}}
function changeTab(id){tab.value=id;offset.value=0;message.value='';loadRows()}
async function findPeople(){const run=++personRevision;try{const result=await communityRequest('/tasks/people?q='+encodeURIComponent(personQuery.value));if(!disposed&&run===personRevision)people.value=result}catch(e){if(run===personRevision&&!disposed)error.value=e.message}}
async function preview(){if(busy.value)return;busy.value=true;error.value='';message.value='';const run=revision;try{const payload={...form.value};const result=await communityRequest('/admin/notice-preview',{method:'POST',body:payload});if(disposed||run!==revision)return;if(!result.recipient_count)throw new Error('该范围暂无接收用户');prepared.value={...payload,recipient_count:result.recipient_count,request_key:crypto.randomUUID()};sendError.value='';dialog.value.showModal()}catch(e){if(!disposed&&run===revision)error.value=e.message}finally{busy.value=false}}
async function send(){if(busy.value||!prepared.value)return;busy.value=true;sendError.value='';const run=revision;try{const {recipient_count,...body}=prepared.value;const result=await communityRequest('/admin/notices',{method:'POST',body});if(disposed||run!==revision)return;message.value='已发送至 '+result.recipient_count+' 位用户';dialog.value.close();prepared.value=null;form.value.title='';form.value.body='';window.dispatchEvent(new CustomEvent('rd:community-updated'))}catch(e){if(!disposed&&run===revision)sendError.value=e.message}finally{busy.value=false}}
function cancel(event){if(busy.value)event.preventDefault()}
onMounted(()=>{load();subscription=window.__api?.auth.onAuthStateChange(event=>{if(event!=='INITIAL_SESSION'){++revision;++rowRevision;dialog.value?.close();prepared.value=null;overview.value=null;rows.value=[];people.value=[];load()}}).data.subscription})
onUnmounted(()=>{disposed=true;++revision;++rowRevision;++personRevision;subscription?.unsubscribe()})
</script>
<style scoped>
.admin-hub{max-width:1240px;margin:auto;padding:40px 24px 80px;color:var(--vp-c-text-1)}.admin-hub header{display:flex;justify-content:space-between;align-items:center;gap:16px}.admin-hub h1{font-size:30px;margin:8px 0 24px}.admin-hub [role=alert]{color:var(--vp-c-brand-1)}.admin-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding:24px 0;border-block:1px solid var(--vp-c-divider);margin-bottom:28px}.admin-metrics div{display:grid;gap:6px}.admin-metrics strong{font-size:28px}.admin-metrics span{font-size:14px;color:var(--vp-c-text-2)}.admin-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:32px}.admin-layout main{min-width:0}.admin-tabs{margin-bottom:24px}.admin-filter{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:16px}.admin-filter label,.admin-notice-form label{display:grid;gap:8px;font-size:14px}.admin-search{flex:1;min-width:140px}.admin-hub input,.admin-hub select,.admin-hub textarea{border:1px solid var(--vp-c-divider);background:var(--vp-c-bg);border-radius:6px;padding:10px 12px;color:inherit;font:inherit;min-width:0;width:100%}.admin-hub select{min-height:42px}.admin-hub textarea{resize:vertical}.admin-queue-row{padding:20px 0;border-bottom:1px solid var(--vp-c-divider);overflow-wrap:anywhere}.admin-row-title{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.admin-row-title>a{font-weight:650}.admin-kind{font-size:12px;color:var(--vp-c-brand-1);background:var(--vp-c-brand-soft);padding:4px 8px;border-radius:4px}.admin-queue-row p{color:var(--vp-c-text-2);font-size:14px;margin:10px 0}.admin-queue-row footer{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:13px;color:var(--vp-c-text-2)}.admin-review-link{margin-left:auto;display:flex;align-items:center;gap:5px;color:var(--vp-c-brand-1)}.admin-queue-row small{font-size:12px;color:var(--vp-c-text-2)}.admin-empty{padding:48px 0;color:var(--vp-c-text-2)}.admin-notice-form{display:grid;gap:20px;max-width:760px}.admin-notice-form>.rd-button{justify-self:start}.admin-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.admin-notice-dialog{width:min(560px,calc(100vw - 32px));max-height:85vh;overflow:auto;border:1px solid var(--vp-c-divider);border-radius:8px;padding:24px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.admin-notice-dialog::backdrop{background:#0006}.admin-notice-dialog h2{font-size:20px}.admin-notice-dialog h3{font-size:18px;margin-top:16px}.admin-preview-body{white-space:pre-wrap;overflow-wrap:anywhere}.admin-notice-dialog p{margin:16px 0}@media(max-width:760px){.admin-hub{padding:28px 16px 60px}.admin-layout{grid-template-columns:1fr;gap:20px}.admin-metrics{gap:12px}.admin-metrics strong{font-size:24px}.admin-form-grid{grid-template-columns:1fr}.admin-tabs{overflow-x:auto;max-width:100%}.admin-queue-row footer{gap:8px}}
</style>
